import * as React from 'react'
import { cn } from '@/lib/rillmark-utils'
export interface EmptyStateProps extends React.HTMLAttributes<HTMLDivElement> { title: string; description: string; icon?: React.ReactNode; action?: React.ReactNode }
export function EmptyState({ title, description, icon, action, className, ...props }: EmptyStateProps) { return <div className={cn('flex flex-col items-center rounded-2xl rounded-tr-md border border-dashed border-input px-6 py-12 text-center', className)} {...props}>{icon && <div aria-hidden="true" className="mb-4 rounded-xl bg-secondary p-3 text-primary">{icon}</div>}<h3 className="text-lg font-semibold">{title}</h3><p className="mt-2 max-w-sm text-sm leading-relaxed text-muted-foreground">{description}</p>{action && <div className="mt-5">{action}</div>}</div> }
